import fs from "node:fs";
import path from "node:path";

/**
 * Block 3 of /test-management: why repositories carry no tests in the estate number
 * (neckarshore-website #370). Data: public/test-scope-reasons.json, generated by
 * scripts/sync-test-scope-reasons.sh. Only released names are rows; other private
 * repositories are counts.
 */
export interface ReasonRow {
  name: string;
  reason: string;
}

export interface ReasonGroup {
  key: string;
  title: string;
  rule?: string;
  rows: ReasonRow[];
  private_count: number;
  private_sentence: string;
}

export interface ScopeReasons {
  measured: string;
  mismatch_line: string;
  groups: ReasonGroup[];
}

export function loadScopeReasons(root: string = process.cwd()): ScopeReasons {
  const file = path.join(root, "public", "test-scope-reasons.json");
  return JSON.parse(fs.readFileSync(file, "utf-8"));
}

/** All repositories in the stats set (public/stats.json `repos`), the tile's denominator. */
export function loadAllRepos(root: string = process.cwd()): number {
  const file = path.join(root, "public", "stats.json");
  return JSON.parse(fs.readFileSync(file, "utf-8")).repos ?? 0;
}

export function groupSize(g: ReasonGroup): number {
  return g.rows.length + g.private_count;
}

/**
 * The block shows its sums only when they add up to the repositories without a count. The daily
 * stats run can move either number; then the block shows the mismatch line instead, and the
 * build does NOT fail over it (#370 data form, point 3).
 */
export function reasonsAddUp(
  reasons: ScopeReasons,
  allRepos: number,
  countedRepos: number,
): boolean {
  const sum = reasons.groups.reduce((acc, g) => acc + groupSize(g), 0);
  return sum === allRepos - countedRepos;
}

/** The one reason every row of a group shares, so the page states it once; else null. */
export function sharedReason(g: ReasonGroup): string | null {
  if (g.rows.length < 2) return null;
  const first = g.rows[0].reason;
  return g.rows.every((r) => r.reason === first) ? first : null;
}
